 save(state);for(const entry of changes){const data=read(entry.file);if((data===null?null:hash(data))!==entry.beforeHash)throw Error('Source changed during preparation: '+entry.file)}
 try{for(const entry of changes)write(entry.file,Buffer.from(entry.after,'base64'));state.status='applied';save(state)}catch(error){restore(state);state.status='restored';save(state);throw error}
